const cmds = [
  ["env", "printf 'GIT_INDEX_FILE=%s\\nHORIZON_LEDGER_GIT_DIR=%s\\nHORIZON_LEDGER_WORK_TREE=%s\\n' \"${GIT_INDEX_FILE-}\" \"$HORIZON_LEDGER_GIT_DIR\" \"$HORIZON_LEDGER_WORK_TREE\""],
  ["head", "\"$HORIZON_GIT\" rev-parse HEAD"],
  ["status", "\"$HORIZON_GIT\" status --short"],
  ["cached-names", "\"$HORIZON_GIT\" diff --cached --name-status HEAD"],
  ["cached-stat", "\"$HORIZON_GIT\" diff --cached --shortstat"],
  ["worktree-stat", "\"$HORIZON_GIT\" diff --stat HEAD"],
  ["recent", "\"$HORIZON_GIT\" log --oneline --decorate -12 -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:20000});
  return `===== ${label} (exit ${r.exit_code ?? "running"}) =====\n${r.output}`;
}));
rs.forEach(text);

const cmds = [
  ["cached", "timeout 30s git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" diff --cached --name-status HEAD"],
  ["cached-stat", "timeout 30s git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" diff --cached --shortstat HEAD"],
  ["status-tracked", "timeout 30s git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" status --porcelain=v1 -uno"],
  ["locks", "find \"$HORIZON_LEDGER_GIT_DIR\" -maxdepth 2 -type f \\( -name '*.lock' -o -name 'index' \\) -printf '%p %s bytes %TY-%Tm-%Td %TH:%TM:%TS\\n'"],
  ["index-count", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" ls-files | wc -l"],
  ["head-paths", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" ls-tree --name-only HEAD -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild | head -20"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000});
  return `===== ${label} exit=${r.exit_code ?? "running"} session=${r.session_id ?? ""} =====\n${r.output}`;
}));
rs.forEach(text);

const cmds = [
  ["status-count", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" status --porcelain=v1 -uno | awk 'BEGIN{m=0;a=0}{if(substr($0,1,2)==\" M\")m++; else if(substr($0,1,2)==\"A \")a++; else if(substr($0,1,2)==\" D\")d++; else if(substr($0,1,2)==\"??\")u++; else o++}END{printf \"modified=%d added=%d deleted=%d untracked=%d other=%d total=%d\\n\",m,a,d,u,o,m+a+d+u+o}'"],
  ["status-top", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" status --porcelain=v1 -uno | awk '{p=$2; sub(\"/.*\",\"\",p); c[p]++} END{for (p in c) print c[p],p}' | sort -nr"],
  ["lean-diff", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" diff --name-status HEAD -- '*.lean'"],
  ["source-diff", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" status --porcelain=v1 -uno | awk '{print $2}' | rg -v '^\\.archon-horizon/|/hgraph/' | head -120"],
  ["lock-stat", "stat -c 'path=%n size=%s mtime=%y' \"$HORIZON_LEDGER_GIT_DIR/next-index-3562430.lock\"; (command -v lsof >/dev/null && lsof \"$HORIZON_LEDGER_GIT_DIR/next-index-3562430.lock\" || true)"],
  ["index-check", "git --git-dir=\"$HORIZON_LEDGER_GIT_DIR\" --work-tree=\"$HORIZON_LEDGER_WORK_TREE\" diff --cached --check HEAD"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:14000});
  return `===== ${label} exit=${r.exit_code ?? "running"} =====\n${r.output}`;
}));
rs.forEach(text);

const cmds = [
  ["inbox-mine", "\"$HORIZON_BIN\" inbox list --mine --status open --json 2>/dev/null | jq '{attention,warnings,counts:([.items[]|.kind]|sort|group_by(.)|map({kind:.[0],count:length}) )}'"],
  ["inbox-global", "\"$HORIZON_BIN\" inbox list --status open --json 2>/dev/null | jq '{attention,warnings,counts:([.items[]|.kind]|sort|group_by(.)|map({kind:.[0],count:length}) )}'"],
  ["horizon-version", "\"$HORIZON_BIN\" --version 2>&1"],
  ["horizon-help", "\"$HORIZON_BIN\" --help 2>&1 | head -100"],
  ["init-help", "\"$HORIZON_BIN\" init --help 2>&1 | head -120"],
  ["skill-stat", "for f in /home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/horizon/SKILL.md /home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/horizon-start/SKILL.md /home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/horizon-inbox/SKILL.md; do sha256sum \"$f\"; done"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:18000});
  return `===== ${label} exit=${r.exit_code ?? "running"} =====\n${r.output}`;
}));
rs.forEach(text);

