data.input:
const cmds = [
  ["config", "rg -n '0\\.1\\.|version|horizon' config.yaml .archon-horizon 2>/dev/null | head -120"],
  ["skills-help", "\"$HORIZON_BIN\" skills --help 2>&1 | head -120"],
  ["skills-list", "\"$HORIZON_BIN\" skills list --json 2>/dev/null | head -200"],
  ["doctor-help", "\"$HORIZON_BIN\" check --help 2>&1 | head -120"],
  ["project-status", "\"$HORIZON_BIN\" project list --json 2>/dev/null | jq '{warnings,projects:[.projects[]|{id,name,path,status}]}'"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:16000});
  return `===== ${label} exit=${r.exit_code ?? "running"} =====\n${r.output}`;
}));
rs.forEach(text);

